// Checks the Swift codec against the golden vectors generated by the Rust
// implementation (protocol/vectors/vectors.json).
import Foundation
import XCTest

@testable import SidecarProtocol

final class VectorTests: XCTestCase {
    struct Vectors: Decodable {
        struct Msg: Decodable {
            let name: String
            let frame_hex: String
        }
        struct PairingV: Decodable {
            let daemon_cert_utf8: String
            let ipad_cert_utf8: String
            let fp_daemon: String
            let fp_ipad: String
            let nonce_daemon: String
            let nonce_ipad: String
            let commitment: String
            let sas: UInt32
            let sas_formatted: String
        }
        let messages: [Msg]
        let pairing: PairingV
    }

    static func loadVectors() throws -> Vectors {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()  // SidecarProtocolTests
            .deletingLastPathComponent()  // Tests
            .deletingLastPathComponent()  // swift
            .deletingLastPathComponent()  // protocol
            .appendingPathComponent("vectors/vectors.json")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    static func sample(_ seq: UInt32, _ phase: PenPhase) -> PenSample {
        PenSample(timestampNs: 1_234_567_890_123 + UInt64(seq) * 4_166_667, seq: seq, phase: phase,
                  flags: SampleFlags.coalesced | SampleFlags.rollValid, x: 0.25, y: 0.75, pressure: 0.5,
                  // Exact bit patterns of Rust's f32 FRAC_PI_4 / FRAC_PI_2 (round to nearest).
                  // Swift's Float.pi rounds toward zero, so Float.pi / 4 is one ULP smaller.
                  altitude: Float(bitPattern: 0x3F49_0FDB), azimuth: Float(bitPattern: 0x3FC9_0FDB), roll: -0.5,
                  zOffset: 0, estimationIndex: 7)
    }

    /// Must build exactly the messages of protocol/rust/tests/vectors.rs.
    static func messages() -> [String: Message] {
        let surface = SurfaceInfo(widthPt: 1180, heightPt: 820, scale: 2, pointsPerInch: 132)
        return [
            "hello": .hello(Hello(channel: .input, trustsPeer: true, caps: Caps.gestures | Caps.haptics,
                                  sessionID: 0x0102_0304_0506_0708, name: "archbox")),
            "hello_ack": .helloAck(HelloAck(trustsPeer: false,
                                            caps: Caps.gestures | Caps.haptics | Caps.roll | Caps.hover,
                                            surface: surface, deviceName: "iPad", model: "iPad Air")),
            "pair_commit": .pairCommit([UInt8](repeating: 0xAA, count: 32)),
            "pair_nonce": .pairNonce([UInt8](repeating: 0xBB, count: 32)),
            "pair_reveal": .pairReveal([UInt8](repeating: 0xCC, count: 32)),
            "pair_decision": .pairDecision(true),
            "goodbye": .goodbye(code: .notPaired, reason: "pair first"),
            "pen_batch": .penBatch(PenBatch(sendTimeNs: 1_234_567_999_999,
                                            samples: [sample(1, .down), sample(2, .move)])),
            "pencil_gesture_squeeze": .pencilGesture(PencilGesture(
                timestampNs: 99, kind: .squeeze, phase: .ended, preferredAction: 5,
                hoverPose: HoverPose(x: 0.5, y: 0.5, zOffset: 0.25, altitude: 1, azimuth: 2, roll: 3))),
            "pencil_gesture_tap": .pencilGesture(PencilGesture(timestampNs: 100, kind: .doubleTap, phase: .discrete,
                                                               preferredAction: 1, hoverPose: nil)),
            "surface_info": .surfaceInfo(surface),
            "haptic": .haptic(Haptic(kind: .alignment, x: 0.5, y: 0.25)),
            "mapping_info": .mappingInfo(MappingInfo(outputName: "DP-1", area: [0, 0, 1, 1])),
            "ping": .ping(Ping(id: 3, t1Ns: 555)),
            "pong": .pong(Pong(id: 3, t1Ns: 555, t2Ns: 1000, t3Ns: 1010)),
            "latency_report": .latencyReport(LatencyReport(samples: 100, p50Us: 4000, p95Us: 6000, p99Us: 9000,
                                                           maxUs: 12000, rttUs: 800)),
            "video_config": .videoConfig(VideoConfig(codec: .hevc, width: 2360, height: 1640, fpsMilli: 60000,
                                                     parameterSets: [[0x40, 0x01], [0x42, 0x01, 0x01],
                                                                     [0x44, 0x01]])),
            "video_frame": .videoFrame(VideoFrame(frameID: 9, keyframe: true, captureNs: 1, encodedNs: 2,
                                                  data: [0, 0, 0, 2, 0x26, 0x01])),
            "video_feedback": .videoFeedback(VideoFeedback(frameID: 9, requestKeyframe: false, receivedNs: 10,
                                                           decodedNs: 20, displayedNs: 30)),
        ]
    }

    func testEncodeMatchesRustVectors() throws {
        let v = try Self.loadVectors()
        let msgs = Self.messages()
        XCTAssertEqual(v.messages.count, msgs.count, "Swift and Rust test sets differ")
        for m in v.messages {
            let msg = try XCTUnwrap(msgs[m.name], "no Swift message named \(m.name)")
            XCTAssertEqual(Pairing.hex(msg.encode()), m.frame_hex, m.name)
        }
    }

    func testDecodeRustVectors() throws {
        let v = try Self.loadVectors()
        let msgs = Self.messages()
        for m in v.messages {
            var d = FrameDecoder()
            // Feed one byte at a time to exercise the incremental decoder.
            for b in try XCTUnwrap(Pairing.parseHex(m.frame_hex)) { d.push([b]) }
            let f = try XCTUnwrap(try d.nextFrame(), m.name)
            XCTAssertEqual(try Message.decode(type: f.type, payload: f.payload), msgs[m.name], m.name)
            XCTAssertEqual(d.buffered, 0)
        }
    }

    func testTrailingBytesIgnoredAndTruncationThrows() throws {
        for (name, m) in Self.messages() {
            if case .videoFrame = m { continue }
            let payload = m.encodePayload()
            XCTAssertEqual(try Message.decode(type: m.typeByte, payload: payload + [0xEE, 0xEE, 0xEE]), m, name)
            for cut in 0..<payload.count {
                XCTAssertThrowsError(try Message.decode(type: m.typeByte, payload: Array(payload[0..<cut])),
                                     "\(name) cut at \(cut)")
            }
        }
    }

    func testPairingMatchesRust() throws {
        let p = try Self.loadVectors().pairing
        let fpD = Pairing.fingerprint(certificateDER: Array(p.daemon_cert_utf8.utf8))
        let fpI = Pairing.fingerprint(certificateDER: Array(p.ipad_cert_utf8.utf8))
        XCTAssertEqual(Pairing.hex(fpD), p.fp_daemon)
        XCTAssertEqual(Pairing.hex(fpI), p.fp_ipad)
        let nD = try XCTUnwrap(Pairing.parseHex(p.nonce_daemon))
        let nI = try XCTUnwrap(Pairing.parseHex(p.nonce_ipad))
        XCTAssertEqual(Pairing.hex(Pairing.commitment(ipadFingerprint: fpI, ipadNonce: nI)), p.commitment)
        let code = Pairing.sas(daemonFingerprint: fpD, ipadFingerprint: fpI, daemonNonce: nD, ipadNonce: nI)
        XCTAssertEqual(code, p.sas)
        XCTAssertEqual(Pairing.formatSAS(code), p.sas_formatted)
        XCTAssertEqual(Pairing.formatSAS(42), "000 042")
    }

    func testUnknownTypeIsPreserved() throws {
        XCTAssertEqual(try Message.decode(type: 0x7E, payload: [1, 2, 3]), .unknown(type: 0x7E, payload: [1, 2, 3]))
    }

    func testFrameDecoderRejectsOversized() {
        var d = FrameDecoder()
        d.push([0xFF, 0xFF, 0xFF, 0x7F])
        XCTAssertThrowsError(try d.nextFrame())
    }
}
